#include <string>
#include <algorithm>
#include <vector>

using namespace std;

int main()
{
  string s, ret;
  bool at = false;
  cin >> s;

  for (auto c : s)
  {
    if (c == 'a' && !at && s.find(c) != 0 && s.find(c) != s.length() - 2)
    {
      ret += '@';
      at = true;
    }
    else if (c == 'd' && c == s[s.find(c) + 1] && s.find(c) != 0 && s.find(c) != s.length() - 3)
    {
      ret += '.';
      s.erase(s.begin() + s.find(c), 3);
    }
    else
      ret += c;
  }

  cout << ret;

  return 0;
}

